use super::*;

#[cfg(unix)]
#[test]
fn executable_check_rejects_regular_file_without_execute_bits() {
    use std::os::unix::fs::PermissionsExt;

    let temp = tempfile::tempdir().unwrap();
    let binary = temp.path().join("ollama");
    std::fs::write(&binary, b"stub").unwrap();
    std::fs::set_permissions(&binary, std::fs::Permissions::from_mode(0o644)).unwrap();
    assert!(!is_executable_file(&binary));

    std::fs::set_permissions(&binary, std::fs::Permissions::from_mode(0o755)).unwrap();
    assert!(is_executable_file(&binary));
}

#[test]
fn build_install_command_on_supported_platform_returns_ok() {
    let directory = tempfile::tempdir().expect("temporary install directory");
    let result = build_install_command(directory.path());
    if cfg!(any(
        target_os = "linux",
        target_os = "macos",
        target_os = "windows"
    )) {
        assert!(result.is_ok(), "supported platform: {result:?}");
    } else {
        assert!(result.is_err(), "unsupported platform");
    }
}

use super::*;

#[test]
fn autosummary_debounce_blocks_repeated_calls_inside_window() {
    let mut config = Config::default();
    config.local_ai.autosummary_debounce_ms = 60_000;
    let service = LocalAiService::new(&config);

    assert!(service.should_run_memory_autosummary(&config));
    assert!(!service.should_run_memory_autosummary(&config));
}

fn test_device(ram_gb: u64) -> DeviceProfile {
    DeviceProfile {
        total_ram_bytes: ram_gb * 1024 * 1024 * 1024,
        cpu_count: 4,
        cpu_brand: String::new(),
        os_name: String::new(),
        os_version: String::new(),
        has_gpu: false,
        gpu_description: None,
    }
}

#[test]
fn bootstrap_defaults_to_disabled_on_low_ram_device() {
    let config = Config::default();
    let device = test_device(4);

    let effective = config_with_recommended_tier_if_unselected(&config, &device);

    assert!(
        !effective.local_ai.runtime_enabled,
        "local_ai.runtime_enabled must default to false on <8 GB device"
    );
}

#[test]
fn bootstrap_defaults_to_disabled_on_sufficient_ram_device() {
    // Local AI is opt-in. Even with >= 8 GB RAM, an unselected tier must
    // leave local AI disabled — the user has to explicitly turn it on.
    let config = Config::default();
    let device = test_device(16);

    let effective = config_with_recommended_tier_if_unselected(&config, &device);

    assert!(
        !effective.local_ai.runtime_enabled,
        "local_ai.runtime_enabled must default to false when no tier selected, regardless of RAM"
    );
}

#[test]
fn bootstrap_honors_opt_in_on_low_ram_device() {
    let mut config = Config::default();
    config.local_ai.selected_tier = Some("ram_2_4gb".to_string());
    config.local_ai.opt_in_confirmed = true;
    crate::service::presets_adapter::apply_preset_to_config(
        &mut config.local_ai,
        crate::presets::ModelTier::Ram2To4Gb,
    );
    let device = test_device(4);

    let effective = config_with_recommended_tier_if_unselected(&config, &device);

    assert!(
        effective.local_ai.runtime_enabled,
        "explicit opt-in must be honored even on low-RAM device"
    );
}

#[test]
fn bootstrap_honors_opt_in_on_sufficient_ram_device() {
    let mut config = Config::default();
    config.local_ai.selected_tier = Some("ram_2_4gb".to_string());
    config.local_ai.opt_in_confirmed = true;
    crate::service::presets_adapter::apply_preset_to_config(
        &mut config.local_ai,
        crate::presets::ModelTier::Ram2To4Gb,
    );
    let device = test_device(16);

    let effective = config_with_recommended_tier_if_unselected(&config, &device);

    assert!(
        effective.local_ai.runtime_enabled,
        "explicit opt-in on sufficient-RAM device must stay enabled"
    );
    assert_eq!(
        effective.local_ai.chat_model_id, config.local_ai.chat_model_id,
        "opt-in config must not be mutated"
    );
}

#[test]
fn bootstrap_overrides_stale_selected_tier_without_opt_in() {
    // Existing install (pre-MVP) had `selected_tier = "ram_2_4gb"` auto-populated
    // by old RAM-based bootstrap logic, but never went through an explicit MVP
    // opt-in. `opt_in_confirmed = false` must hard-override to disabled.
    let mut config = Config::default();
    config.local_ai.runtime_enabled = true;
    config.local_ai.selected_tier = Some("ram_2_4gb".to_string());
    config.local_ai.opt_in_confirmed = false;
    let device = test_device(16);

    let effective = config_with_recommended_tier_if_unselected(&config, &device);

    assert!(
        !effective.local_ai.runtime_enabled,
        "stale selected_tier without opt_in_confirmed must be hard-overridden to disabled"
    );
    assert_eq!(
        effective.local_ai.selected_tier.as_deref(),
        Some("ram_2_4gb"),
        "bootstrap must leave the persisted selected_tier untouched — only the effective `enabled` flips"
    );
}

use super::*;

#[test]
fn sanitize_inline_completion_handles_placeholders_and_clamps_length() {
    assert_eq!(sanitize_inline_completion("none", "hello"), "");
    assert_eq!(sanitize_inline_completion("n/a", "hello"), "");
    assert_eq!(
        sanitize_inline_completion("\"- hello world\"", "hello"),
        "hello world"
    );

    let long = "a".repeat(256);
    let out = sanitize_inline_completion(&long, "hello");
    assert_eq!(out.chars().count(), 96);
}

#[test]
fn sanitize_inline_completion_strips_arrow_and_extra_whitespace() {
    assert_eq!(
        sanitize_inline_completion("\t→  keep   it concise\t", "hello"),
        "keep it concise"
    );
}

#[test]
fn sanitize_inline_completion_strips_quoted_generation_label() {
    assert_eq!(
        sanitize_inline_completion("\"suffix: hello\"", "context example"),
        "hello"
    );
}

#[test]
fn sanitize_inline_completion_returns_suffix_only_when_model_repeats_context() {
    let ctx = "Yesterday, I went";
    let raw = "Yesterday, I went to the garden";
    assert_eq!(sanitize_inline_completion(raw, ctx), "to the garden");
}

#[test]
fn sanitize_inline_completion_drops_tabby_unicode_noise() {
    let ctx = "Yester";
    let raw = "Yester\tday, \u{2028}I went\t to garden";
    assert_eq!(
        sanitize_inline_completion(raw, ctx),
        "day, I went to garden"
    );
}

#[test]
fn sanitize_inline_completion_preserves_iso_date_prefix() {
    assert_eq!(
        sanitize_inline_completion("2026-04-07", "context example"),
        "2026-04-07"
    );
}

#[test]
fn sanitize_inline_completion_preserves_time_prefix() {
    assert_eq!(
        sanitize_inline_completion("3pm meeting", "context example"),
        "3pm meeting"
    );
}

#[test]
fn sanitize_inline_completion_preserves_double_dash_help_token() {
    assert_eq!(
        sanitize_inline_completion("--help", "context example"),
        "--help"
    );
}

#[test]
fn sanitize_inline_completion_preserves_task_marker_without_space() {
    assert_eq!(
        sanitize_inline_completion("-[ ] task", "context example"),
        "-[ ] task"
    );
}

#[test]
fn sanitize_inline_completion_strips_numbered_list_prefix_dot() {
    assert_eq!(
        sanitize_inline_completion("1. item", "context example"),
        "item"
    );
}

#[test]
fn sanitize_inline_completion_strips_numbered_list_prefix_paren() {
    assert_eq!(
        sanitize_inline_completion("2) item", "context example"),
        "item"
    );
}

#[test]
fn accidental_one_character_overlap_is_preserved() {
    assert_eq!(
        sanitize_inline_completion("takes a nap", "The cat"),
        "takes a nap"
    );
}

use super::*;

const REQUIRED: u64 = 8_192;

#[test]
fn at_or_above_minimum_is_accepted() {
    let exact = evaluate_context(Some(8_192), REQUIRED);
    assert!(exact.is_accepted());
    assert_eq!(
        exact,
        ContextEligibility::Ok {
            context_length: 8_192
        }
    );

    let above = evaluate_context(Some(32_768), REQUIRED);
    assert!(above.is_accepted());
    assert!(!above.is_rejected());
}

#[test]
fn below_minimum_is_rejected_with_required_floor() {
    let verdict = evaluate_context(Some(2_048), REQUIRED);
    assert!(verdict.is_rejected());
    assert!(!verdict.is_accepted());
    assert_eq!(
        verdict,
        ContextEligibility::BelowMinimum {
            context_length: 2_048,
            required: 8_192,
        }
    );
}

#[test]
fn unknown_context_is_neither_accepted_nor_rejected() {
    let verdict = evaluate_context(None, REQUIRED);
    assert!(!verdict.is_accepted());
    assert!(!verdict.is_rejected());
    assert_eq!(verdict, ContextEligibility::Unknown { required: 8_192 });
}

#[test]
fn eligibility_serializes_tagged() {
    let json = serde_json::to_value(evaluate_context(Some(4_096), REQUIRED)).unwrap();
    assert_eq!(json["status"], "below_minimum");
    assert_eq!(json["context_length"], 4_096);
    assert_eq!(json["required"], 8_192);

    let ok = serde_json::to_value(evaluate_context(Some(8_192), REQUIRED)).unwrap();
    assert_eq!(ok["status"], "ok");
    assert_eq!(ok["context_length"], 8_192);

    let unknown = serde_json::to_value(evaluate_context(None, REQUIRED)).unwrap();
    assert_eq!(unknown["status"], "unknown");
    assert_eq!(unknown["required"], 8_192);
}

use super::*;

#[test]
fn parse_valid_response() {
    let r = parse_sentiment_response("joy positive 0.9");
    assert_eq!(r.emotion, "joy");
    assert_eq!(r.valence, "positive");
    assert!((r.confidence - 0.9).abs() < 0.01);
}

#[test]
fn parse_valid_negative() {
    let r = parse_sentiment_response("anger negative 0.75");
    assert_eq!(r.emotion, "anger");
    assert_eq!(r.valence, "negative");
    assert!((r.confidence - 0.75).abs() < 0.01);
}

#[test]
fn parse_unknown_emotion_falls_back() {
    let r = parse_sentiment_response("excited positive 0.8");
    assert_eq!(r.emotion, "neutral");
    assert_eq!(r.valence, "positive");
}

#[test]
fn parse_too_few_tokens() {
    let r = parse_sentiment_response("joy");
    assert_eq!(r.emotion, "neutral");
    assert_eq!(r.valence, "neutral");
}

#[test]
fn parse_extra_tokens_returns_neutral() {
    let r = parse_sentiment_response("joy positive 0.9 explanation");
    assert_eq!(r.emotion, "neutral");
    assert_eq!(r.valence, "neutral");
    assert_eq!(r.confidence, 1.0);
}

#[test]
fn parse_bad_confidence() {
    let r = parse_sentiment_response("sadness negative abc");
    assert_eq!(r.emotion, "sadness");
    assert_eq!(r.valence, "negative");
    assert!((r.confidence - 0.5).abs() < 0.01);
}

#[test]
fn parse_clamps_confidence() {
    let r = parse_sentiment_response("joy positive 2.5");
    assert!((r.confidence - 1.0).abs() < 0.01);
}

#[test]
fn parse_empty_returns_neutral() {
    let r = parse_sentiment_response("");
    assert_eq!(r.emotion, "neutral");
    assert_eq!(r.valence, "neutral");
}

#[test]
fn parse_clamps_negative_confidence_to_zero() {
    let r = parse_sentiment_response("joy positive -0.5");
    assert!(r.confidence >= 0.0 && r.confidence <= 1.0);
    assert!((r.confidence - 0.0).abs() < 0.01);
}

#[test]
fn parse_unknown_valence_falls_back_to_neutral() {
    let r = parse_sentiment_response("joy mixed 0.8");
    assert_eq!(r.emotion, "joy");
    assert_eq!(r.valence, "neutral");
}

#[test]
fn parse_accepts_all_documented_emotions() {
    for e in [
        "joy", "sadness", "anger", "surprise", "fear", "disgust", "neutral",
    ] {
        let r = parse_sentiment_response(&format!("{e} positive 0.5"));
        assert_eq!(r.emotion, e, "emotion `{e}` should be accepted verbatim");
    }
}

#[test]
fn parse_accepts_all_documented_valences() {
    for v in ["positive", "negative", "neutral"] {
        let r = parse_sentiment_response(&format!("joy {v} 0.5"));
        assert_eq!(r.valence, v, "valence `{v}` should be accepted verbatim");
    }
}

#[test]
fn neutral_constructor_returns_documented_defaults() {
    let r = SentimentResult::neutral();
    assert_eq!(r.emotion, "neutral");
    assert_eq!(r.valence, "neutral");
    assert!((r.confidence - 1.0).abs() < 0.01);
}

#[test]
fn non_finite_confidence_uses_fallback() {
    let result = parse_sentiment_response("joy positive NaN");
    assert_eq!(result.confidence, 0.5);
}

use super::*;
use crate::model::ProviderError;

#[test]
fn structured_status_ignores_unanchored_numbers() {
    assert_eq!(
        structured_http_status("API error (403 Forbidden): nope"),
        Some(403)
    );
    assert_eq!(structured_http_status("HTTP 404 Not Found"), Some(404));
    assert_eq!(structured_http_status("status: 401"), Some(401));
    assert_eq!(structured_http_status("408 Request Timeout"), Some(408));
    assert_eq!(structured_http_status("upstream took 450ms"), None);
    assert_eq!(structured_http_status("gpt-4-0409 returned nothing"), None);
}

#[test]
fn provider_failure_taxonomy_is_complete() {
    assert_eq!(
        classify_provider_failure(Some(401), None, "invalid api key"),
        ProviderFailureClass::NonRetryable
    );
    assert_eq!(
        classify_provider_failure(Some(429), None, "too many requests"),
        ProviderFailureClass::RateLimited
    );
    assert_eq!(
        classify_provider_failure(Some(429), None, "insufficient_balance"),
        ProviderFailureClass::NonRetryableRateLimit
    );
    assert_eq!(
        classify_provider_failure(None, None, "503 Service Unavailable"),
        ProviderFailureClass::UpstreamUnhealthy
    );
    assert_eq!(
        classify_provider_failure(None, None, "api key not set"),
        ProviderFailureClass::NonRetryable
    );
}

#[test]
fn structured_status_takes_precedence_over_message_heuristics() {
    assert_eq!(
        classify_provider_failure(Some(400), None, "proxy said bad gateway"),
        ProviderFailureClass::NonRetryable
    );
    assert_eq!(
        classify_provider_failure(None, Some("invalid_request"), "502 bad gateway"),
        ProviderFailureClass::NonRetryable
    );
}

#[test]
